import {computeE6B,dialAngle,factorAtAngle} from './e6b.mjs';
const fields={wind:[['course','True course','°T',90],['tas','True airspeed','kt',120],['wind_from','Wind from','°T',45],['wind_speed','Wind speed','kt',20]],time:[['speed','Groundspeed','kt',120],['distance','Distance','NM',180],['time','Time','min',90]],fuel:[['rate','Fuel flow','gal/h',8],['fuel','Usable fuel','US gal',40],['time','Flight time','min',120]],altitude:[['elevation','Field elevation','ft',2500],['altimeter','Altimeter','inHg',29.92],['temperature','Outside temperature','°C',25]],dial:[['factor','Multiplier','×',2],['input','Input value','',30]]};
const modes=[['wind','Wind'],['time','Time & distance'],['fuel','Fuel'],['altitude','Altitude'],['dial','Slide rule']];
const values=Object.fromEntries(Object.entries(fields).map(([mode,fs])=>[mode,Object.fromEntries(fs.map(([id,l,u,v])=>[id,v]))]));
let mode='wind',solve={time:'time',fuel:'time'};
const format=n=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:1}):'—';
function scale(radius){let markup='';for(let n=10;n<100;n++){const angle=Math.log10(n/10)*Math.PI*2,x=180+Math.sin(angle)*radius,y=180-Math.cos(angle)*radius,major=n%10===0||n===15||n===25||n===75;const r=radius-(major?10:5);markup+=`<line x1="${x}" y1="${y}" x2="${180+Math.sin(angle)*r}" y2="${180-Math.cos(angle)*r}"/>`;if(major){const textR=radius-21;markup+=`<text x="${180+Math.sin(angle)*textR}" y="${180-Math.cos(angle)*textR}" text-anchor="middle" dominant-baseline="central">${n}</text>`;}}return markup;}
function dial(){return `<svg class="e6b-dial" id="e6b-dial" viewBox="0 0 360 360" role="slider" tabindex="0" aria-label="Slide-rule multiplier. Drag to rotate or use arrow keys." aria-valuemin="0.1" aria-valuemax="100" aria-valuenow="${values.dial.factor}"><circle class="dial-outer" cx="180" cy="180" r="174"/>${scale(165)}<g id="e6b-inner" transform="rotate(${dialAngle(Number(values.dial.factor))} 180 180)"><circle class="dial-inner" cx="180" cy="180" r="126"/>${scale(121)}<path class="dial-index" d="m180 49-6 12h12Z"/></g><circle class="dial-hub" cx="180" cy="180" r="65"/><text class="dial-title" x="180" y="175" text-anchor="middle">E6B</text><text x="180" y="197" text-anchor="middle">RATIO SCALE</text></svg>`;}
function windDiagram(d){const scale=100/Math.max(d.tas,d.gs,d.wind,1),origin={x:150,y:155},vec=(speed,bearing)=>({x:Math.sin(bearing*Math.PI/180)*speed*scale,y:-Math.cos(bearing*Math.PI/180)*speed*scale}),air=vec(d.tas,d.heading),ground=vec(d.gs,d.course),ax=origin.x+air.x,ay=origin.y+air.y,gx=origin.x+ground.x,gy=origin.y+ground.y;return `<svg class="e6b-wind" viewBox="0 0 300 310" role="img" aria-label="Wind triangle: blue air vector, grey wind vector, green ground vector."><defs><marker id="e6b-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto-start-reverse"><path d="M0 0 6 3 0 6Z" fill="context-stroke"/></marker></defs><circle cx="150" cy="155" r="135"/><path class="wind-grid" d="M150 20v270M15 155h270"/><text x="150" y="17" text-anchor="middle">N</text><g marker-end="url(#e6b-arrow)"><line class="wind-air" x1="${origin.x}" y1="${origin.y}" x2="${ax}" y2="${ay}"/><line class="wind-vector" x1="${ax}" y1="${ay}" x2="${gx}" y2="${gy}"/><line class="wind-ground" x1="${origin.x}" y1="${origin.y}" x2="${gx}" y2="${gy}"/></g></svg><div class="e6b-legend"><span>● Air</span><span>● Wind</span><span>● Ground</span></div>`;}
export function mountE6B(modal){
 modal.className='e6b-modal';
 const render=()=>{
  const choices=mode==='time'?[['time','Time'],['distance','Distance'],['speed','Groundspeed']]:mode==='fuel'?[['time','Endurance'],['fuel','Fuel needed'],['rate','Fuel flow']]:[];
  modal.innerHTML=`<div class="between"><div><span class="feature-label">FLIGHT COMPUTER</span><h2 id="modal-title">E6B</h2></div><button class="icon-btn" data-modal-close aria-label="Close E6B"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M7.5 7.5l9 9 M16.5 7.5l-9 9"/></svg></button></div><div class="e6b-tabs" role="tablist" aria-label="E6B functions">${modes.map(([id,label])=>`<button role="tab" aria-selected="${mode===id}" data-e6b-mode="${id}">${label}</button>`).join('')}</div>${choices.length?`<div class="e6b-solve"><span>Solve for</span><div class="segmented" role="group" aria-label="Solve for">${choices.map(([id,label])=>`<button data-e6b-solve="${id}" class="${solve[mode]===id?'active':''}" aria-pressed="${solve[mode]===id}">${label}</button>`).join('')}</div></div>`:''}<div class="e6b-fields">${fields[mode].filter(([id])=>!choices.length||id!==solve[mode]).map(([id,label,unit])=>`<label>${label}<span class="e6b-input"><input inputmode="decimal" type="number" step="any" id="e6b-${id}" data-e6b-input="${id}" value="${values[mode][id]}" aria-label="${label}, ${unit}"><span>${unit}</span></span></label>`).join('')}</div>${mode==='dial'?`<p class="small muted">Drag the inner scale, or adjust the multiplier above.</p>${dial()}`:''}<div id="e6b-results" aria-live="polite"></div><a class="e6b-reference" href="https://www.faa.gov/sites/faa.gov/files/18_phak_ch16.pdf" target="_blank" rel="noopener noreferrer">FAA PHAK · Navigation</a>`;
  modal.setAttribute('aria-labelledby','modal-title');update();wireDial();
 };
 const update=()=>{const target=modal.querySelector('#e6b-results');try{const result=computeE6B(mode,values[mode],solve[mode]);target.innerHTML=`<div class="e6b-results">${result.rows.map(([label,value,unit])=>`<div><span>${label}</span><strong>${format(value)} <small>${unit}</small></strong></div>`).join('')}</div><p class="e6b-note">${result.note}</p>${result.diagram?windDiagram(result.diagram):''}`;if(mode==='dial'){modal.querySelector('#e6b-inner').setAttribute('transform',`rotate(${dialAngle(Number(values.dial.factor))} 180 180)`);modal.querySelector('#e6b-dial').setAttribute('aria-valuenow',values.dial.factor);}}catch(error){target.innerHTML='';const p=document.createElement('p');p.className='e6b-error';p.textContent=error.message;target.append(p);}};
 const wireDial=()=>{const svg=modal.querySelector('#e6b-dial');if(!svg)return;let drag=null;const pointAngle=e=>{const r=svg.getBoundingClientRect();return Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2)*180/Math.PI;};const setFactor=n=>{values.dial.factor=Math.max(.1,Math.min(100,n));modal.querySelector('#e6b-factor').value=Number(values.dial.factor.toFixed(3));update();};svg.onpointerdown=e=>{e.preventDefault();drag={angle:pointAngle(e),rotation:dialAngle(Number(values.dial.factor))};svg.setPointerCapture(e.pointerId);};svg.onpointermove=e=>{if(!drag)return;const next=pointAngle(e);let delta=next-drag.angle;if(delta>180)delta-=360;if(delta< -180)delta+=360;drag.angle=next;drag.rotation=Math.max(-360,Math.min(720,drag.rotation+delta));setFactor(factorAtAngle(drag.rotation));};svg.onpointerup=svg.onpointercancel=()=>drag=null;svg.onkeydown=e=>{if(['ArrowLeft','ArrowDown','ArrowRight','ArrowUp'].includes(e.key)){e.preventDefault();setFactor(Number(values.dial.factor)*10**((['ArrowLeft','ArrowDown'].includes(e.key)?-1:1)/360));}};};
 modal.onclick=e=>{const tab=e.target.closest('[data-e6b-mode]'),op=e.target.closest('[data-e6b-solve]');if(tab){mode=tab.dataset.e6bMode;render();}if(op){solve[mode]=op.dataset.e6bSolve;render();}};
 modal.oninput=e=>{if(e.target.dataset.e6bInput){values[mode][e.target.dataset.e6bInput]=e.target.value;update();}};
 modal.addEventListener('close',()=>{modal.onclick=null;modal.oninput=null;},{once:true});render();
}
